def make_floor():
 # One finite connected deck, two whole upright posts and a slim full cross rail.
 # Ladle bowl and baster remain on the deck; the original ladle hook meets the upper rail.
 cy=.06551712348919282
 boxes=[((-.30,-.20,0),(.30,.20,.018))]
 for x in [-.225,-.035]:boxes.append(((x-.007,cy-.0095,.018),(x+.007,cy+.0095,.355)))
 boxes.append(((-.232,cy-.004,.355),(-.028,cy+.004,.363)))
 # Normalize equivalent box ends before union so float32 export cannot collapse microscopic strips.
 boxes=[(tuple(round(x,9)for x in lo),tuple(round(x,9)for x in hi))for lo,hi in boxes]
 axes=[sorted(set(p[k]for b in boxes for p in b))for k in range(3)];boundary={};faces=[(0,3,2,1),(4,5,6,7),(0,1,5,4),(1,2,6,5),(2,3,7,6),(3,0,4,7)]
 for i in range(len(axes[0])-1):
  for j in range(len(axes[1])-1):
   for k in range(len(axes[2])-1):
    x0,x1=axes[0][i:i+2];y0,y1=axes[1][j:j+2];z0,z1=axes[2][k:k+2];mid=((x0+x1)/2,(y0+y1)/2,(z0+z1)/2)
    if not any(all(lo[t]<mid[t]<hi[t]for t in range(3))for lo,hi in boxes):continue
    v=[(x0,y0,z0),(x1,y0,z0),(x1,y1,z0),(x0,y1,z0),(x0,y0,z1),(x1,y0,z1),(x1,y1,z1),(x0,y1,z1)]
    for f in faces:
     q=tuple(v[t]for t in f);key=tuple(sorted(q))
     if key in boundary:del boundary[key]
     else:boundary[key]=q
 ts=[]
 for q in boundary.values():
  mat=0 if all(p[2]<=.018 for p in q)else 1
  for f in[(0,1,2),(0,2,3)]:ts.append((tuple(q[i]for i in f),mat))
 mats=[{'name':n,'doubleSided':True,'pbrMetallicRoughness':{'baseColorFactor':color,'metallicFactor':0.,'roughnessFactor':rough}}for n,color,rough in [('SceneWholeWarmLowRestDeck',[.35,.29,.19,1],.81),('SceneWholeDeepTealUprightsAndRail',[.075,.17,.16,1],.69)]]
 return ts,mats


def main():
 import bpy,sys,time
 from mathutils import Vector
 OUT=Path(__file__).resolve().parent
 inputs={k:zlib.decompress(base64.b64decode(v['compressed']))for k,v in INPUTS.items()}
 for k,raw in inputs.items():assert hashlib.sha256(raw).hexdigest()==INPUTS[k]['sha256']
 for v in SOURCE_INPUTS.values():assert hashlib.sha256(zlib.decompress(base64.b64decode(v['compressed']))).hexdigest()==v['sha256']
 document,blob,proof=compose(inputs);model=pack_glb(document,blob);(OUT/'model.glb').write_bytes(model)
