 scene.world=scene.world or bpy.data.worlds.new('Neutral whole ladle and baster open rail rest');scene.world.use_nodes=True;scene.world.node_tree.nodes['Background'].inputs['Color'].default_value=(.3,.3,.3,1);scene.world.node_tree.nodes['Background'].inputs['Strength'].default_value=.8
